import React, { useState } from 'react';
import { gameService } from '../lib/gameService.js';

interface VotingPanelProps {
  puzzleId: string;
  wordA: string;
  wordB: string;
  onVoteSubmitted: () => void;
}

export const VotingPanel: React.FC<VotingPanelProps> = ({
  puzzleId,
  wordA,
  wordB,
  onVoteSubmitted
}) => {
  const [voted, setVoted] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  const handleVote = async (choice: string) => {
    setLoading(true);
    try {
      await gameService.submitVote(puzzleId, wordA, wordB, choice);
      setVoted(choice);
      setTimeout(onVoteSubmitted, 500);
    } catch (error) {
      console.error('Vote submission failed:', error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="w-full max-w-md mx-auto p-6 bg-white rounded-lg shadow-lg">
      <h3 className="text-lg font-bold mb-4 text-center">Which fits better?</h3>
      
      <div className="grid grid-cols-2 gap-4">
        <button
          onClick={() => handleVote(wordA)}
          disabled={loading || voted !== null}
          className={`p-4 rounded-lg font-semibold text-lg transition-all ${
            voted === wordA
              ? 'bg-blue-500 text-white'
              : 'bg-gray-200 hover:bg-gray-300'
          } ${voted === wordB ? 'opacity-50' : ''}`}
        >
          {wordA}
        </button>
        
        <button
          onClick={() => handleVote(wordB)}
          disabled={loading || voted !== null}
          className={`p-4 rounded-lg font-semibold text-lg transition-all ${
            voted === wordB
              ? 'bg-blue-500 text-white'
              : 'bg-gray-200 hover:bg-gray-300'
          } ${voted === wordA ? 'opacity-50' : ''}`}
        >
          {wordB}
        </button>
      </div>

      {voted && (
        <p className="text-center text-sm text-gray-600 mt-4">
          Thanks for voting!
        </p>
      )}
    </div>
  );
};
